(() => {
  'use strict';
  const $ = id => document.getElementById(id);
  const appClock=BusAppClock.create(),appNow=()=>appClock.now();
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const today = () => new Intl.DateTimeFormat('en-CA', {timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(appNow()));
  const dateLabel = date => new Intl.DateTimeFormat('ja-JP',{timeZone:'Asia/Tokyo',month:'long',day:'numeric',weekday:'short'}).format(new Date(date+'T12:00:00+09:00'));
  const defaults = ['広島駅@HiroshimaArea','八丁堀@HiroshimaArea','広島バスセンター@HiroshimaArea'];
  function stored(key, fallback) { try { const value=JSON.parse(localStorage.getItem(key)); return value ?? fallback; } catch { return fallback; } }
  const S = { date:today(), pinned:false, tab:'home', group:'', pole:'', dest:'', mode:'realtime', route:'',
    center:{lat:34.3967466,lon:132.4742327}, nearby:[], vehicles:[], meta:null, detail:null, timetable:null,
    favorites:stored('hiroshima_bus_favorites_v2',stored('hiroshima_bus_favorites_v1', defaults)), poleIds:[], company:'', relevant:true, mapVisible:false,animation:true,simulations:[],
    revision:0, renderedRevision:-1, refreshing:null, again:false, forceQueued:false, selectedTrip:null, search:'', kana:'', searchCompany:'', dataState:null };
  if (!Array.isArray(S.favorites)) S.favorites=[...defaults];
  S.favorites=S.favorites.map(f=>typeof f==='string'?{group_id:f,pole_ids:[],name:f.split('@')[0],labels:[]}:f).filter(f=>f&&typeof f.group_id==='string'&&Array.isArray(f.pole_ids)).map(f=>({...f,pole_ids:[...new Set(f.pole_ids.filter(v=>typeof v==='string'&&v))].sort(),labels:Array.isArray(f.labels)?f.labels:[]}));
  S.favorites=S.favorites.filter((f,i,a)=>a.findIndex(v=>favoriteKey(v)===favoriteKey(f))===i);
  let map, markers, poles, vehiclesLayer, routeLayer, locationLayer, currentTile, searchTimer, areaTimer, dataTimer;
  let suppressMap=false, lastGeneration=-1, lastDataUpdated=0, lastFocus=null, modalAbort=null, dataLoadEnd=null;
  // Signage UI 0.6.0: independent measured GPS and timetable simulation modes.
  Object.assign(S,{positionModes:stored('hiroshima_bus_position_modes_v2',{vehicles:true,single:true}),navRoot:'home',showPrevious:true,gps:null,mapKind:null,mapViews:{},returnTab:'home',singleVehicle:null,follow:false,rows:null,rowContext:'',pendingRows:[],touching:false,interactionUntil:0,readNotices:stored('hiroshima_bus_read_notices_v3',[]),notices:stored('hiroshima_bus_notices_v3',[])});
  if(!S.positionModes||typeof S.positionModes!=='object')S.positionModes={vehicles:true,single:true};
  if(!Array.isArray(S.readNotices))S.readNotices=[];
  if(!Array.isArray(S.notices))S.notices=[];
  const vehicleMarkers=new Map();
  let followFrame=0,followTarget=null,followPanning=false;
  // Global radar display defaults do not alter remote polling.
  const radarDisplay={correction:'forward',fps:15};
  const radarZoomKey='hiroshima_bus_radar_zoom_unlocked_v1';
  let radarZoomUnlocked=stored(radarZoomKey,false)===true;
  const motionPaths=new Map(),motionFailures=new Map(),motionQueue=[];let motionRequests=0,motionFrame=0,motionPaint=0,motionLayoutAt=0;
  const motionKey=v=>`${v.company}|${v.trip_id}|${v.service_date||today()}`;
  function requestMotionPath(v){
    const key=motionKey(v);if(!S.animation||motionPaths.has(key)||Date.now()-(motionFailures.get(key)||0)<30000)return;
    motionPaths.set(key,null);motionQueue.push({key,company:v.company,trip_id:v.trip_id,service_date:v.service_date});pumpMotionPaths();
  }
  function pumpMotionPaths(){
    while(motionRequests<3&&motionQueue.length){
      const jobs=motionQueue.splice(0,12);motionRequests++;
      api('/api/routes/profiles',{requests:JSON.stringify(jobs.map(({company,trip_id,service_date})=>({company,trip_id,service_date})))}).then(data=>{
        jobs.forEach((job,i)=>{const p=data.profiles[i];motionPaths.set(job.key,BusRouteMotion.profile(p.points,p.stops));motionFailures.delete(job.key);});scheduleMotionRender();
        while(motionPaths.size>1536)motionPaths.delete(motionPaths.keys().next().value);
      }).catch(()=>{for(const job of jobs){motionPaths.delete(job.key);motionFailures.set(job.key,Date.now());}}).finally(()=>{motionRequests--;pumpMotionPaths();});
    }
  }
  const htmlCache=new WeakMap();
  let motionRenderTimer=null;
  function scheduleMotionRender(){if(motionRenderTimer||!S.mapVisible)return;motionRenderTimer=setTimeout(()=>{motionRenderTimer=null;renderMap();startVehicleMotion();},80);}

  function qs(values) { return new URLSearchParams(Object.entries(values).filter(([,v])=>v!==undefined && v!==null)).toString(); }
  async function api(path, values={}, foreground=false) {
    const end=foreground?BusBrandMotion.begin():null;let failed=false;
    try {
    if(window.BusLocalAPI){const started=performance.now(),data=await window.BusLocalAPI.request(path,values);if(path==='/api/meta'&&data.clock_sync){appClock.accept(data.clock_sync,started,performance.now());setTimeout(()=>{if(!S.pinned&&S.date!==today())changeDate(today(),false);},0);}return data;}
    const started=performance.now();
    const res=await fetch(path+'?'+qs(values),{cache:'no-store'});
    const data=await res.json();
    if(path==='/api/meta'&&data.clock_sync){appClock.accept(data.clock_sync,started,performance.now());setTimeout(()=>{if(!S.pinned&&S.date!==today())changeDate(today(),false);},0);}
    if (!res.ok || data.error) throw new Error(data.error || 'データを読み込めませんでした');
    return data;
    }catch(e){failed=true;throw e;}finally{end?.(failed);}
  }
  function toast(message) { $('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500); }
  function error(message='') { $('error-message').textContent=message;$('error-message').hidden=!message; }
  function age(epoch) { if (!epoch) return '時刻未取得'; const sec=Math.max(0,Math.round(appNow()/1000-epoch));return sec<60?`${sec}秒前`:`${Math.floor(sec/60)}分前`; }
  function stamp(epoch,label='更新') { return epoch?`<span class="position-age" data-age="${epoch}" data-age-label="${esc(label)}">${age(epoch)}${esc(label)}</span>`:''; }
  function distance(m) {return m>=1000?`${(m/1000).toFixed(1)} km`:`${m} m`;}
  function favoriteKey(f){return JSON.stringify([f.group_id,[...f.pole_ids].sort()]);}
  function selectedPoles(){return S.poleIds.length?S.poleIds:S.pole?[S.pole]:[];}
  function poleParams(ids=selectedPoles()){return ids.length>1?{pole_ids:JSON.stringify(ids)}:{pole_id:ids[0]||''};}
  function favoriteScope(f){return f.pole_ids.length?(f.labels.length?f.labels.join('・'):f.pole_ids.length+'か所ののりば'):'すべてののりば';}
  function favoriteCard(f,d=null,note=''){
    const preview=(d?.upcoming||[]).filter(b=>!['cancelled','skipped','deleted'].includes(b.status)).slice(0,2);
    return `<article class="stop-card" data-key="${esc(favoriteKey(f))}"><button data-action="favorite" data-favorite="${esc(favoriteKey(f))}"><span class="stop-name">★ ${esc(d?.name||f.name||f.group_id.split('@')[0])}</span><p class="stop-meta">${esc(favoriteScope(f))}</p>${note?`<p class="stop-meta">${esc(note)}</p>`:''}${preview.map(b=>`<p class="stop-preview">${esc(timeText(b))} ${esc(b.headsign)} ${b.source==='prediction'?'〔予測〕':'〔定刻〕'}</p>`).join('')}</button></article>`;
  }
  function saveFavorites() { try {localStorage.setItem('hiroshima_bus_favorites_v2',JSON.stringify(S.favorites));} catch {toast('お気に入りを保存できませんでした');renderHomeFavorites();return false;}renderHomeFavorites();return true; }
  function renderHomeFavorites(){patch($('home-favorites'),S.favorites.length?S.favorites.map(f=>favoriteCard(f)).join(''):'<div class="empty-state">バス停の☆を押すと登録できます。</div>');}
  function boardablePoles(){return (S.detail?.poles||[]).filter(p=>p.is_boardable!==false&&p.stop_no!=='降車');}
  function poleChoice(p,type,name,checked){const number=poleNumber(p.stop_no),label=poleOption(p),description=number?label.replace('［'+number+'］','').trim():label;return `<label class="pole-choice"><span class="pole-choice-number">${esc(number)}</span><span class="pole-choice-description">${esc(description||'乗車場所')}</span><input type="${type}" name="${name}" value="${esc(p.same_pole_id)}" ${checked?'checked':''} aria-label="${esc(label)}"></label>`;}
  function renderPoleTrigger(){
    const ids=selectedPoles(),selected=boardablePoles().filter(p=>ids.includes(p.same_pole_id));
    $('btn-pole-picker').disabled=!S.detail;
    $('btn-pole-picker').textContent=ids.length>1?`選択した${ids.length}か所ののりば　⌄`:ids.length?(selected.length?poleOption(selected[0]):'選択したのりば')+'　⌄':'すべてののりば　⌄';
  }
  function openPolePicker(){
    if(!S.detail)return;
    const ids=selectedPoles(),eligible=S.dest?S.detail.eligible_pole_ids:null;
    const choices=boardablePoles().filter(p=>!eligible||eligible.includes(p.same_pole_id)||ids.includes(p.same_pole_id));
    $('pole-picker-choices').innerHTML=`<label class="pole-choice"><span class="pole-choice-all">すべてののりば</span><input type="radio" name="stop-pole" value="" ${!ids.length?'checked':''}></label>`+(ids.length>1?`<label class="pole-choice"><span class="pole-choice-all">選択した${ids.length}か所ののりば</span><input type="radio" name="stop-pole" value="__saved__" checked></label>`:'')+choices.map(p=>poleChoice(p,'radio','stop-pole',ids.length===1&&ids[0]===p.same_pole_id)).join('');
    $('pole-picker-dialog').showModal();document.querySelector('#pole-picker-choices input:checked')?.focus();
  }
  function renderFavoriteEditor(){
    const saved=S.favorites.filter(f=>f.group_id===S.group);
    $('favorite-existing').innerHTML=saved.length?'<p>登録済み</p>'+saved.map(f=>`<div class="favorite-existing-row"><span>${esc(favoriteScope(f))}</span><button data-action="remove-favorite" data-favorite="${esc(favoriteKey(f))}" aria-label="${esc(favoriteScope(f))}のお気に入りを解除">解除</button></div>`).join(''):'';
    const custom=$('favorite-scope-poles').checked;$('favorite-pole-choices').hidden=!custom;
    $('btn-save-favorite').disabled=custom&&!document.querySelector('#favorite-pole-choices input:checked');
  }
  function openFavoriteEditor(){
    if(!S.detail)return;
    const ids=selectedPoles();$('favorite-stop-name').textContent=S.detail.name;
    $('favorite-scope-all').checked=!ids.length;$('favorite-scope-poles').checked=!!ids.length;
    $('favorite-pole-choices').innerHTML=boardablePoles().map(p=>poleChoice(p,'checkbox','favorite-pole',ids.includes(p.same_pole_id))).join('');
    renderFavoriteEditor();$('favorite-dialog').showModal();
  }
  function saveFavoriteSelection(){
    const ids=$('favorite-scope-poles').checked?[...document.querySelectorAll('#favorite-pole-choices input:checked')].map(i=>i.value).sort():[];
    if($('favorite-scope-poles').checked&&!ids.length)return;
    const f={group_id:S.group,name:S.detail.name,pole_ids:ids,labels:boardablePoles().filter(p=>ids.includes(p.same_pole_id)).map(p=>poleOption(p))};
    const index=S.favorites.findIndex(v=>favoriteKey(v)===favoriteKey(f));if(index>=0)S.favorites[index]=f;else S.favorites.unshift(f);
    if(!saveFavorites())return;$('favorite-dialog').close();renderDetail(S.detail);toast('お気に入りに登録しました');
  }

  // Preserve keyed nodes, focus, open details and the reader's scroll anchor.
  function morph(oldNode, newNode) {
    if (oldNode.nodeType!==newNode.nodeType || oldNode.nodeName!==newNode.nodeName) {oldNode.replaceWith(newNode);return;}
    if (oldNode.nodeType===Node.TEXT_NODE) {if(oldNode.data!==newNode.data)oldNode.data=newNode.data;return;}
    if (!(oldNode instanceof Element)) return;
    for(const a of [...oldNode.attributes]) if(!newNode.hasAttribute(a.name) && !(oldNode.tagName==='DETAILS'&&a.name==='open'))oldNode.removeAttribute(a.name);
    for(const a of [...newNode.attributes]) if(oldNode.getAttribute(a.name)!==a.value)oldNode.setAttribute(a.name,a.value);
    if(oldNode.tagName==='INPUT' && document.activeElement!==oldNode && oldNode.type!=='search') oldNode.value=newNode.value;
    if(oldNode.tagName==='INPUT' && oldNode.type==='checkbox')oldNode.checked=newNode.checked;
    const keyed=new Map([...oldNode.childNodes].filter(n=>n.nodeType===1 && n.dataset.key).map(n=>[n.dataset.key,n]));
    let cursor=oldNode.firstChild;
    for(const fresh of [...newNode.childNodes]) {
      let existing=fresh.nodeType===1 && fresh.dataset.key?keyed.get(fresh.dataset.key):cursor;
      if(existing && fresh.nodeType===1 && fresh.dataset.key && existing.dataset?.key!==fresh.dataset.key)existing=null;
      if(existing?.nodeType===1 && existing.dataset.key && !(fresh.nodeType===1&&fresh.dataset.key))existing=null;
      if(existing) {if(existing!==cursor)oldNode.insertBefore(existing,cursor);const after=existing.nextSibling;morph(existing,fresh);cursor=after;}
      else {oldNode.insertBefore(fresh,cursor);}
    }
    while(cursor){const next=cursor.nextSibling;cursor.remove();cursor=next;}
  }
  function patch(element,html) {
    if(!element || htmlCache.get(element)===html)return;
    const deck=element.id==='trip-timeline-list'?element:$('content-deck');
    const anchor=[...element.children].find(n=>n.dataset.key && n.getBoundingClientRect().top>=deck.getBoundingClientRect().top);
    const before=anchor?.getBoundingClientRect().top;const key=anchor?.dataset.key;
    const fresh=element.cloneNode(false);fresh.innerHTML=html;
    morph(element,fresh);htmlCache.set(element,html);
    if(key){const after=[...element.children].find(n=>n.dataset.key===key);if(after)deck.scrollTop+=after.getBoundingClientRect().top-before;}
  }
  function options(element, choices, value, placeholder) {
    const html=`<option value="">${esc(placeholder)}</option>`+choices.map(c=>`<option value="${esc(c.value)}">${esc(c.label)}</option>`).join('');
    if(element.dataset.options!==html){const focus=document.activeElement===element;patch(element,html);element.dataset.options=html;if(focus)element.focus({preventScroll:true});}
    element.value=value;
  }
  const itemKey = u => `${u.company}|${u.trip_id}|${u.service_date}|${u.stop_sequence}`;
  const tripAttrs = u => `data-company="${esc(u.company)}" data-trip-id="${esc(u.trip_id)}" data-date="${esc(u.service_date)}" data-stop-sequence="${esc(u.stop_sequence||'')}"`;
  function timeText(u) {return u.realtime_time || u.scheduled_time || '時刻未取得';}
  function delayText(u) {
    if(u.status==='cancelled')return '運休';
    if(u.status==='skipped')return 'この停留所には停車しません';
    if(u.departure_state==='waiting')return '出発待ち';
    if(!u.delay_known)return '時刻表のみ・運行状況未取得';
    const minutes=Math.abs(Math.round(u.delay_sec/60));
    return u.delay_sec>0?`${minutes<1?'1分未満':minutes+'分'}遅れ`:u.delay_sec<0?`${minutes<1?'1分未満':minutes+'分'}早い予測`:'遅延なしの予測';
  }
  function departureCard(u) {
    const inactive=['cancelled','skipped','deleted'].includes(u.status), predicted=u.source==='prediction';
    const departed=u.departure_confirmed===true;
    const status=departed?'発車済み':inactive?delayText(u):u.departure_state==='waiting'?'出発待ち':predicted?delayText(u):'予測なし';
    return `<article class="departure-card ${esc(u.status)} ${departed?'departed':''}" data-key="${esc(itemKey(u))}"><button class="departure-row" data-action="trip" ${tripAttrs(u)} style="${companyStyle(u.company)}" aria-label="${esc(timeText(u)+' '+u.headsign+' '+status)}"><span class="departure-time">${esc(timeText(u))}<small>${departed?esc(status):predicted?`${u.event_kind==='arrival'?'到着予測':'予定'} ${esc(u.scheduled_time)}`:'時刻表'}</small></span><span class="destination"><span class="route-badge">${esc(u.route_short_name||'—')}</span>${esc(u.headsign||'行先未取得')}<span class="departure-meta">${companyTag(u.company)}${esc(status)}${u.added?'・臨時':''}</span></span>${poleBadge(u.stop_no)}</button></article>`;
  }
  function poleNumber(value){const n=String(value||'').trim();return !n||/^(番号なし|なし|不明|[-—－])$/.test(n)?'':n;}
  function unnumberedPlace(group=S.group,name=''){return group==='広島バスセンター@HiroshimaArea'||name==='広島バスセンター'?'降車ホーム':'乗車場所';}
  function poleBadge(value){const n=poleNumber(value),place=unnumberedPlace();return n?`<span class="pole-label"><b>${esc(n)}</b>のりば</span>`:`<span class="pole-label unnumbered"><b>${place==='降車ホーム'?'降車<br>ホーム':'乗車<br>場所'}</b></span>`;}
  function poleOption(p){
    const n=poleNumber(p.stop_no);
    const clean=v=>{let s=String(v||'').trim().replace(/^(?:番号なし|番号無し)\s*(?:[\/／・:：]\s*)?/,'');if(n){const e=n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');s=s.replace(new RegExp('^(?:[［\\[]'+e+'[］\\]]|'+e+'(?:\\s*(?:番)?のりば)?)(?:\\s+|[\\/／・:：]\\s*|$)'),'');}return s.trim();};
    const text=[...new Set((p.directions||[]).map(clean).map(v=>v.replace(/^[\/／・:：]\s*/, '')).filter(Boolean))].join('・');
    return `${n?'［'+n+'］':''}${text?' '+text:''}`.trim()||unnumberedPlace();
  }
  function scheduledFallback(row){
    if(row.departure_confirmed)return {...row,departed:true};
    return {...row,source:'schedule',realtime_source:'schedule',realtime_time:'',predicted_epoch:null,delay_sec:null,delay_min:null,delay_known:false,event_kind:'departure',status:['cancelled','skipped','deleted'].includes(row.status)?row.status:'scheduled',departed:false,elapsed:false,departure_confirmed:false};
  }
  function stableDepartures(d) {
    const context=[S.group,S.date,JSON.stringify(selectedPoles()),S.dest,d.service_date].join('|');
    const incoming=d.upcoming,index=new Map(incoming.map(v=>[itemKey(v),v])),passed=new Set(d.departed_keys||[]);
    if(S.rowContext!==context||!S.rows){S.rowContext=context;S.rows=incoming.map(v=>({...v}));}
    else S.rows=S.rows.map(old=>{
      const key=itemKey(old);
      if(passed.has(key)||old.departure_confirmed)return {...old,departed:true,departure_confirmed:true};
      if(index.has(key))return {...index.get(key),departed:false,departure_confirmed:false};
      return scheduledFallback(old);
    });
    S.pendingRows=incoming;
    const changed=S.rows.map(itemKey).join('\n')!==incoming.map(itemKey).join('\n');
    $('btn-apply-departures').hidden=!changed;
    const additions=incoming.filter(v=>!S.rows.some(r=>itemKey(r)===itemKey(v))).length;
    $('btn-apply-departures').textContent=`新しい発車一覧に切替${additions?' · '+additions+'件追加':''}`;
    if(S.touching||Date.now()<S.interactionUntil){S.rowPaintPending=true;return;}
    S.rowPaintPending=false;
    patch($('upcoming-bus-list'),S.rows.length?S.rows.map(departureCard).join(''):`<div class="empty-state">${esc(stateMessage(d))}</div>`);
  }
  function stopCard(g) {
    const preview=(g.next_buses||[]).filter(b=>!['cancelled','skipped','deleted'].includes(b.status)).slice(0,2);
    return `<article class="stop-card" data-key="${esc(g.group_id)}"><button data-action="stop" data-group="${esc(g.group_id)}"><span class="stop-name">${S.favorites.some(f=>f.group_id===g.group_id)?'★ ':''}${esc(g.name)}</span>${g.distance_m!==undefined?`<span class="stop-distance">${distance(g.distance_m)}</span>`:''}<p class="stop-meta">${esc(g.hira||g.kana||'')} ／ ${g.pole_count}のりば</p>${preview.map(b=>`<p class="stop-preview">${esc(timeText(b))} ${esc(b.headsign)} ${b.source==='prediction'?(b.event_kind==='arrival'?'〔到着予測〕':'〔発車予測〕'):'〔定刻〕'}</p>`).join('')}</button></article>`;
  }
  function stateMessage(detail) {
    if(detail.service_state==='out_of_range')return '選択日の時刻表データが有効期間外です。「設定 → 時刻表データ」から更新してください。';
    const expired=(detail.coverage||[]).filter(c=>!c.available);
    if(expired.length)return `${expired.map(c=>c.name).join('・')}の時刻表は有効期間外です。表示されない便があります。「設定 → 時刻表データ」から更新してください。`;
    if(detail.next_service_date)return `本日の掲載便は終了しました。${dateLabel(detail.next_service_date)}の始発便を表示しています。`;
    if(detail.service_state==='no_service')return 'この日・のりば・目的地に該当する掲載便はありません。条件や日付をご確認ください。';
    if(S.date!==today())return `${dateLabel(S.date)}の運行日データを表示中。リアルタイムの接近情報ではありません。`;
    return '位置情報を取得できない路線・便は定刻での表示を行っています。';
  }

  function initMap() {
    if(map||!window.L)return;
    map=L.map('transit-map',{zoomControl:false,minZoom:3,maxZoom:19,maxBounds:[[-85,-180],[85,180]],maxBoundsViscosity:1}).setView([S.center.lat,S.center.lon],16);
    L.control.zoom({position:'bottomright'}).addTo(map);
    markers=L.layerGroup().addTo(map);poles=L.layerGroup().addTo(map);vehiclesLayer=L.layerGroup().addTo(map);routeLayer=L.layerGroup().addTo(map);locationLayer=L.layerGroup().addTo(map);drawGPS();
    setTheme(document.documentElement.dataset.theme||'light');
    map.on('dragstart zoomstart',()=>{if(!suppressMap){S.follow=false;renderFollow();}});
    map.on('click',()=>{if(S.mapKind==='vehicles'&&S.selectedTrip)clearRadarSelection();});
    map.on('moveend',()=>{
      // Following is a camera update, not a new viewport search/render request.
      if(followPanning)return;
      renderMap();if(suppressMap)return;
      if(S.mapKind==='map')$('btn-search-this-area').hidden=false;
      else if(S.mapKind==='vehicles'){clearTimeout(areaTimer);areaTimer=setTimeout(()=>{const c=map.getCenter();S.center={lat:c.lat,lon:c.lng};S.revision++;refresh();},350);}
    });
  }
  function setTheme(theme) {
