  function clusters(items,size=64) {
    const parent=items.map((_,i)=>i),buckets=new Map(),points=[];
    const root=i=>{while(parent[i]!==i){parent[i]=parent[parent[i]];i=parent[i];}return i;};
    items.forEach((item,i)=>{
      const p=map.project([item.lat,item.lon],map.getZoom());points.push(p);
      const x=Math.floor(p.x/size),y=Math.floor(p.y/size);
      for(let dx=-1;dx<=1;dx++)for(let dy=-1;dy<=1;dy++){
        for(const j of buckets.get(`${x+dx}:${y+dy}`)||[]){const q=points[j];if(Math.hypot(p.x-q.x,p.y-q.y)<size)parent[root(i)]=root(j);}
      }
      const key=`${x}:${y}`;if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(i);
    });
    const groups=new Map();items.forEach((item,i)=>{const key=root(i);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(item);});
    return [...groups.values()];
  }
