    demandTask=(async()=>{
      while(sentDemand!==wantedDemand){const value=wantedDemand;await api('/api/realtime/demand',{enabled:value?1:0});sentDemand=value;}
    })().finally(()=>{demandTask=null;});
    return demandTask;
  }
